Method.Implementation:
 $$$TRACE("...In insertUpdatePerson method")
 Set ..Adapter.WebServiceClientClass = "EnterprisePersonService.SOAP11Endpoint"
 Set tSC = $$$OK
 set errTxt = ""
 Set tSC = ..Adapter.InvokeMethod("insertUpdatePerson",.patientIdElement,pRequest.Patient,pRequest.sourceSystemIdentification,pRequest.codeSystem,.warnings)
 $$$TRACE("...In insertUpdatePerson method .. Status.."_tSC)         
 if ('tSC){
   set errText = $System.Status.GetErrorText(tSC)
   $$$TRACE("...In insertUpdatePerson method. Error --> "_errText)    
   If errText["ERROR #6242:"{	
      $$$TRACE("...In insertUpdatePerson method. ERROR #6242 ")
      //set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                  	          	    
   }      		     	     	          
   If errText["ERROR #6248:"{	        	          	    
   		if ((errText["INITIATE_ENOREC")){		 					 			
		   set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
		}
	 	if ((errText["INITIATE_ESTATUS")){		 			
			set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
		}		        
		If errTxt["INITIATE_EEXISTS" {
		    $$$TRACE("...In insertUpdatePerson method .. SKIPPING the RECORD.."_errTxt)
		    set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
		}else{ 			    			       
            set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
        }   	     	     	          
   }
   If errText["ERROR #6059:"{	
   	    set tSC = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
   }
 }else{
     $$$TRACE("...In insertUpdatePerson method .. NO ERROR")
     Set tSC = pRequest.NewResponse(.pResponse)  Quit:$$$ISERR(tSC) tSC 
  	 $$$TRACE("...In insertUpdatePerson method .. Warnings "_$get(warnings))
  	 $$$TRACE("...In insertUpdatePerson method .. ErrorNotification::"_$get(errNotification))
     Set pResponse.patientIdElement=$get(patientIdElement),pResponse.warnings = $get(warnings)
     if ($length(pResponse.patientIdElement) > 0){
		 $$$TRACE("...Patient MRN: "_pResponse.patientIdElement)
	 }else{
	 	 set tSC = $$$ERROR(6246,"Exception in InsertAddUpdate Initiate Webservice Operation")	 	 
 	 }
     $$$TRACE("...In insertUpdatePerson method .. DONE!!!!!!")     
  }
  Quit tSC

 $$$TRACE("...In mergePerson method")
  Set ..Adapter.WebServiceClientClass = "EnterprisePersonService.SOAP11Endpoint"
  try{
  	 Set tSC = ..Adapter.InvokeMethod("mergePerson",.patientIdElement,pRequest.Patient,pRequest.sourceSystemIdentification,pRequest.codeSystem,.warnings)
  	 if ('tSC){
     	set errText = $System.Status.GetErrorText(tSC)
     	$$$TRACE("...In mergePerson method .. "_errText)     	
     	If errText["ERROR #6248:"{	        	          	    
     	            throw $$$ERROR(6248," Soap Fault Exception in MergePerson Response: "_errText)   	     	     	          
     	}
     	If errText["ERROR #6059:"{	
     	    throw $$$ERROR(6059," Error while communicationg with Initiate server: "_errText)     	    
     	}
     }else{
	     $$$TRACE("...In MergePerson method .. NO ERROR")
	     }
  }CATCH exceptionvar {
	   set errTxt = $System.Status.GetErrorText(exceptionvar)	
	   $$$TRACE("...In mergePerson method .. exceptionvar.. Catch Block.."_errTxt)     
	   set errTxt = $System.Status.GetErrorText(%objlasterror)	    
	  $$$TRACE("...In mergePerson method .. Catch Block.."_errTxt)	 	         										
   }

   if ('tSC){
   		set errTxt = $System.Status.GetErrorText(%objlasterror)	    
   		$$$TRACE("...In MergePerson method .. ERROR TEXT.."_errTxt)	

   		If errTxt["ERROR #6248:"{	
   				if ((errText["INITIATE_ENOREC")){		 					 			
		 			set status = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
		 			Quit $$$OK
	 			}
	 			if ((errText["INITIATE_ESTATUS")){		 			
		 			set status = ##class(IHC.ITF.ITFCOMMON.Utility).InputDataError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
		 			Quit $$$OK
	 			}		        
		          If errTxt["INITIATE_EEXISTS" {
			          $$$TRACE("...In mergePerson method .. SKIPPING the RECORD.."_errTxt)
			          set status = ##class(IHC.ITF.ITFCOMMON.Utility).SkipMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
			          Quit $$$OK
		          }else{ 			    			       
                     set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
                     Quit $$$OK
		          }
	    }
	    If errTxt["ERROR #6059:"{			       
                set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError("Out-Initiate-Demogr-XML-Soap", errTxt)                                 
                Quit $$$OK
		}
   }

  Set tSC = pRequest.NewResponse(.pResponse)  Quit:$$$ISERR(tSC) tSC
  $$$TRACE("...In MergePerson method .. Warnings "_$get(warnings))
  $$$TRACE("...In MergePerson method .. ErrorNotification::"_$get(errNotification))

  Set pResponse.patientIdElement=$get(patientIdElement),pResponse.warnings = $get(warnings)

  if ($length(pResponse.patientIdElement) > 0){
	 $$$TRACE("...Patient MRN: "_pResponse.patientIdElement)
	 	 }else{
		 	 set tSC = $$$ERROR(6246,"Exception in MergePerson Initiate Webservice Operation")
		 	 Quit tSC		 	 
		 	 }
   $$$TRACE("...In MergePerson method .. DONE!!!!!!") 

 Quit tSC
